<template>
 <section :class="['marking-library',{drawer,closed:drawer&&!opened}]" :style="drawer?{width:opened?width+'px':'46px'}:undefined" aria-label="花纹库" tabindex="0" @keydown="libraryKey">
  <div class="library-heading"><strong v-if="opened||!drawer">{{zh?'花纹库':localize('Marking library')}} · {{regions.length}}</strong><button v-if="drawer" :aria-expanded="opened" @click="opened=!opened">{{opened?'‹':'›'}}</button></div>
  <template v-if="opened||!drawer">
   <input v-model="search" :placeholder="zh?'搜索名称、类别或颜色':localize('Search names, groups or colors')" aria-label="搜索花纹">
   <div class="library-batch"><button :disabled="store.busy||!regions.length" @click="checked=regions.map(r=>r.piece.id)">{{zh?'全选花纹':localize('Select all')}}</button><button :disabled="!checked.length" @click="checked=[]">{{zh?'取消全选':localize('Clear selection')}}</button><button :disabled="store.busy||!checked.length" @click="pendingDelete=[...checked]">{{zh?'删除所选':localize('Delete selected')}} · {{checked.length}}</button></div>
   <div v-if="pendingDelete.length" role="alertdialog" :aria-label="zh?'确认删除花纹':localize('Confirm deletion')" class="delete-confirm"><p>{{zh?'删除所选花纹及其关联贴附？可通过撤销恢复；锁定花纹会阻止整批删除。':localize('Delete sources and their placements? Undo restores them; locked sources prevent the entire operation.')}} {{pendingDelete.length}}</p><button :disabled="store.busy" @click="deleteIds(pendingDelete)">{{zh?'确认删除':localize('Confirm delete')}}</button><button @click="pendingDelete=[]">{{zh?'取消':localize('Cancel')}}</button></div>
   <label class="library-zoom">{{zh?'预览缩放':localize('Preview scale')}}<input v-model.number="zoom" type="range" min=".6" max="2" step=".1"><span>{{Math.round(zoom*100)}}%</span></label>
   <p v-if="drawer" class="drag-help">{{zh?'将花纹拖到可见模型表面，松开即按毫米尺寸贴附。中键旋转检查，每次拖放生成独立副本。':localize('Drop onto the visible model to attach at its millimetre size. Middle-drag to inspect; each drop creates an independent copy.')}}</p><LegacyProjection v-if="drawer" :language="language"/>
   <div ref="libraryContent" class="library-content" :style="region?{gridTemplateRows:`minmax(50px,${1-detailShare}fr) 8px minmax(100px,${detailShare}fr)`}:undefined"><div class="library-groups"><section v-for="group in groups" :key="group.key"><h3>{{group.label}}</h3><div class="region-grid" :style="{'--region-size':100*zoom+'px','--preview-height':85*zoom+'px'}"><div v-for="r in group.items" :key="r.piece.id" class="region-tile"><button :data-region-id="r.piece.id" :draggable="drawer&&!store.busy" @dragstart="dragSource($event,r.piece.id)" @dragend="endSourceDrag" :class="['region-card',{active:selected===r.piece.id}]" @click="cardClick($event,r.piece.id)" @dblclick="emit('edit',r.piece.id)"><svg :viewBox="box(r.piece)"><path :d="piecePath(r.piece)" :fill="r.piece.color" fill-rule="evenodd" stroke="var(--text-muted)" vector-effect="non-scaling-stroke" stroke-width="1.25" stroke-linejoin="round"/></svg><small>{{r.piece.name}}</small></button><input class="region-check" type="checkbox" :checked="checked.includes(r.piece.id)" :aria-label="(zh?'选择花纹 ':localize('Select marking '))+r.piece.name" @change="toggleChecked(r.piece.id)"><button class="region-delete" :disabled="store.busy" :aria-label="(zh?'删除花纹 ':localize('Delete marking '))+r.piece.name" @click="deleteIds([r.piece.id])">×</button></div></div></section><p v-if="regions.length&&!filtered.length" role="status">{{zh?'没有匹配的花纹，请修改搜索内容。':localize('No matching markings. Try a different search.')}}</p><p v-if="!regions.length">{{zh?'在花纹提取页上传设定图，提取的花纹会显示在这里。':localize('Upload a reference sheet on the extraction page to populate this library.')}}</p></div>
   <div v-if="region" class="detail-resizer" role="separator" tabindex="0" aria-orientation="horizontal" :aria-valuenow="Math.round(detailShare*100)" :aria-label="zh?'调整花纹详情高度':localize('Resize marking details')" @pointerdown="detailDrag=true;($event.currentTarget as HTMLElement).setPointerCapture($event.pointerId);$event.preventDefault()" @pointermove="resizeDetail" @pointerup="endDetail" @pointercancel="endDetail" @lostpointercapture="endDetail" @keydown.up.prevent="detailShare=Math.min(.9,detailShare+.05);endDetail()" @keydown.down.prevent="detailShare=Math.max(.2,detailShare-.05);endDetail()" @dblclick="detailShare=.68;endDetail()"><span/></div><section v-if="region" class="region-settings"><button class="primary open-marking-editor" :disabled="store.busy" @click="emit('edit',region.piece.id)"><ToolIcon name="brushAdd"/>{{zh?'打开花纹修改页':localize('Open marking editor')}}</button><small>{{zh?'在独立大画布中查看选区，用画笔补全或擦除花纹。':localize('Inspect the selection on a large canvas, then paint or erase the marking.')}}</small>
    <p v-if="attachNotice" class="attach-notice" role="status">{{attachNotice}}</p><fieldset class="source-metadata" :disabled="store.busy">
    <label>{{zh?'名称':localize('Name')}}<input :value="region.piece.name" maxlength="120" @change="metadata('name',($event.target as HTMLInputElement).value)"></label>
    <div class="two-col"><label>{{zh?'部位分类':localize('Body part')}}<select :value="region.anatomy?.part??'unknown'" aria-label="花纹部位分类" @change="classify(($event.target as HTMLSelectElement).value as BodyPart,region.anatomy?.side??'unknown')"><option v-for="part in bodyParts" :key="part" :value="part">{{partName(part,zh)}}</option></select></label><label>{{zh?'角色左右侧':localize('Character side')}}<select :value="region.anatomy?.side??'unknown'" aria-label="花纹左右侧" @change="classify(region.anatomy?.part??'unknown',($event.target as HTMLSelectElement).value as BodySide)"><option v-for="side in (['center','left','right','unknown'] as const)" :key="side" :value="side">{{sideName(side,zh)}}</option></select></label></div><small v-if="region.anatomy?.method==='silhouette-1'">{{zh?'部位是位置建议，不是语义识别。角与耳朵边界不明确的区域保留为待分类；请核对原图后选择角或耳朵及左右侧。':localize('Position hint only. Ambiguous horn/ear regions remain unclassified; inspect the artwork and set the part and side.')}}</small><label>{{zh?'制作方式':localize('Fabrication')}}<select :value="region.fabrication??'sewn'" aria-label="花纹制作方式" @change="fabrication(($event.target as HTMLSelectElement).value as 'sewn'|'detail')"><option value="sewn">{{zh?'缝制色块':localize('Sewn material')}}</option><option value="detail">{{zh?'印绘／贴花细节':localize('Printed / applique detail')}}</option></select></label><small v-if="region.fabrication==='detail'">{{zh?'保留图形、贴附和纸样上的细节，不沿它生成裁线或独立裁片。':localize('Keep the artwork on the model and paper patterns without separate sewing cuts.')}}</small><div class="two-col"><label>{{zh?'分类':localize('Category')}}<input :value="region.category" maxlength="80" @change="metadata('category',($event.target as HTMLInputElement).value)"></label><label>{{zh?'颜色':localize('Color')}}<input type="color" :value="region.piece.color" @change="metadata('color',($event.target as HTMLInputElement).value)"></label></div>
    </fieldset>
    <template v-if="drawer"><button class="primary" :disabled="store.busy||!store.data.project?.surface||!placementAnatomies(region).some(a=>a.part!=='unknown')" @click="autoAttach">{{zh?'自动匹配此花纹的模型部位':localize('Automatically match this source')}}</button><small>{{zh?'将此花纹拖到可见模型表面，可直接选择贴附位置。':localize('Drag this marking onto the visible model to choose its position.')}}</small></template>
    <button class="danger" :disabled="store.busy" @click="remove">{{zh?'删除此花纹':localize('Delete marking source')}}</button>
   </section></div>
  </template>
  <div v-if="drawer&&opened" class="drawer-resizer" role="separator" aria-label="调整花纹抽屉宽度" @pointerdown="start" @pointermove="drag" @pointerup="resize=undefined;endDetail()" @pointercancel="resize=undefined"></div>
 </section>
</template>

<script setup lang="ts">
import {placementAnatomies} from '../../../packages/reference/placement-context';
import {localize} from './localization';

import {placementReason} from './modules/mappingFeedback';
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import {bodyParts,partName,sideName,type BodyPart,type BodySide} from '../../../packages/reference/body-parts';
import LegacyProjection from './LegacyProjection.vue';
import ToolIcon from './ToolIcon.vue';
import {useSession} from './store';
import {piecePath,pointBounds} from '../../../packages/pattern/edit';
import type {Project,Piece} from '../../../packages/schema/index';
type Region=NonNullable<Project['patternLibrary']>[number];
const props=defineProps<{language:'zh'|'en';targetId?:string;drawer?:boolean}>(),store=useSession(),zh=computed(()=>props.language==='zh');
const emit=defineEmits<{select:[id:string];edit:[id:string]}>();
function selectRegion(id:string){selected.value=id;emit('select',id);}
const attachNotice=ref(''),checked=ref<string[]>([]),pendingDelete=ref<string[]>([]);
function toggleChecked(id:string){checked.value=checked.value.includes(id)?checked.value.filter(x=>x!==id):[...checked.value,id];}
async function deleteIds(ids:string[]){const p=store.data.project;if(!p||!ids.length||store.busy)return;if(await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'library.regions.delete',pieceIds:[...ids]}))){checked.value=checked.value.filter(id=>!ids.includes(id));pendingDelete.value=[];}}
function libraryKey(e:KeyboardEvent){if((e.target as HTMLElement).closest('input,select,textarea,[contenteditable],.open-marking-editor'))return;if(e.key==='Delete'){e.preventDefault();e.stopPropagation();const ids=checked.value.length?checked.value:selected.value?[selected.value]:[];if(ids.length===1)void deleteIds(ids);else pendingDelete.value=[...ids];}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();e.stopPropagation();checked.value=regions.value.map(r=>r.piece.id);}}

const libraryContent=ref<HTMLElement>(),detailShare=ref(.68);
const detailDrag=ref(false);
function resizeDetail(e:PointerEvent){if(!detailDrag.value||!libraryContent.value)return;const b=libraryContent.value.getBoundingClientRect();detailShare.value=Math.max(.2,Math.min(.9,1-(e.clientY-b.top)/b.height));}
function endDetail(){detailDrag.value=false;try{localStorage.setItem('fpcad.library.detail',String(detailShare.value));localStorage.setItem('fpcad.library.width',String(width.value));}catch{}}
onMounted(()=>{try{const d=Number(localStorage.getItem('fpcad.library.detail')),w=Number(localStorage.getItem('fpcad.library.width'));if(d>=.2&&d<=.9)detailShare.value=d;if(w>=240)width.value=Math.min(w,window.innerWidth*.6);}catch{}});
const selected=ref(''),search=ref(''),zoom=ref(1),width=ref(300),opened=ref(true);
const narrow=window.matchMedia('(max-width:1100px)'),fitDrawer=()=>{if(props.drawer&&narrow.matches)opened.value=false;};
onMounted(()=>{fitDrawer();narrow.addEventListener('change',fitDrawer);});onBeforeUnmount(()=>narrow.removeEventListener('change',fitDrawer));
const regions=computed(()=>store.data.project?.patternLibrary??[]),region=computed(()=>regions.value.find(r=>r.piece.id===selected.value));
const filtered=computed(()=>regions.value.filter(r=>(r.piece.name+r.category+partName(r.anatomy?.part??'unknown',zh.value)+r.piece.color).toLowerCase().includes(search.value.toLowerCase())));
const groups=computed(()=>bodyParts.map(part=>({key:part,label:partName(part,zh.value),items:filtered.value.filter(r=>(r.anatomy?.part??'unknown')===part)})).filter(group=>group.items.length));
watch(()=>props.targetId,id=>{if(!id)selectRegion('');else if(regions.value.some(r=>r.piece.id===id))selectRegion(id);},{immediate:true});
watch(selected,()=>{attachNotice.value='';});
watch(regions,list=>{checked.value=checked.value.filter(id=>list.some(r=>r.piece.id===id));if(!list.some(r=>r.piece.id===selected.value))selected.value='';});
function box(piece:Piece){const b=pointBounds(piece.nodes);return `${b.minX-5} ${-b.maxY-5} ${b.maxX-b.minX+10} ${b.maxY-b.minY+10}`;}
async function put(next:Region){const p=store.data.project;if(p)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'library.region.put',region:JSON.parse(JSON.stringify(next))}));}
async function metadata(field:'name'|'color'|'category',value:string){const r=region.value;if(!r)return;await put(field==='category'?{...r,category:value}:{...r,piece:{...r.piece,[field]:value}});}
async function classify(part:BodyPart,side:BodySide){const r=region.value;if(r)await put({...r,category:partName(part),anatomy:{part,side,confidence:1,method:'manual'}});}
async function fabrication(value:'sewn'|'detail'){const r=region.value;if(r)await put({...r,fabrication:value});}
async function autoAttach(){const p=store.data.project,r=region.value;if(p&&r){attachNotice.value='';await store.run(async()=>{const result=await window.fpcad.autoPlaceMarkings(p.id,p.revision,[r.piece.id]);if(result.ok){const report=result.autoPlacementReport;attachNotice.value=report?.placed?(zh.value?'已贴附，请旋转模型检查并确认位置。':localize('Attached. Rotate, inspect and approve the position.')):(report?.skipped.map(item=>placementReason(item.reason,zh.value)).join(' · ')??'');}return result;});}}
async function remove(){const p=store.data.project,r=region.value;if(p&&r)await store.run(()=>window.fpcad.apply(p.id,p.revision,{type:'library.region.delete',pieceId:r.piece.id}));}
let draggedUntil=0;
function cardClick(event:MouseEvent,id:string){if(performance.now()<draggedUntil)return;selectRegion(id);if(event.ctrlKey||event.metaKey)toggleChecked(id);}
function endSourceDrag(){draggedUntil=performance.now()+200;}
function dragSource(event:DragEvent,id:string){
 if(store.busy||!props.drawer||!event.dataTransfer){event.preventDefault();return;}
 // Dragging must not open the source editor or resize the model viewport.
 draggedUntil=performance.now()+200;const transfer=event.dataTransfer;transfer.setData('application/x-fpcad-region',id);transfer.effectAllowed='copy';
 const svg=(event.currentTarget as HTMLElement).querySelector('svg'),piece=regions.value.find(r=>r.piece.id===id)?.piece,matrix=svg?.getScreenCTM();
 if(!svg||!piece||!matrix)return;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse()),bounds=pointBounds(piece.nodes);
 if(point.x>=bounds.minX&&point.x<=bounds.maxX&&-point.y>=bounds.minY&&-point.y<=bounds.maxY)transfer.setData('application/x-fpcad-anchor',JSON.stringify({xMm:point.x,yMm:-point.y}));
 const rect=svg.getBoundingClientRect(),ghost=svg.cloneNode(true) as SVGSVGElement;ghost.style.cssText=`position:fixed;left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px;pointer-events:none;z-index:-1;background:transparent;opacity:.85`;document.body.appendChild(ghost);transfer.setDragImage(ghost,Math.max(0,Math.min(rect.width,event.clientX-rect.left)),Math.max(0,Math.min(rect.height,event.clientY-rect.top)));requestAnimationFrame(()=>ghost.remove());
}
let resize:{x:number;width:number}|undefined;
function start(event:PointerEvent){resize={x:event.clientX,width:width.value};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);}
function drag(event:PointerEvent){if(resize)width.value=Math.max(240,Math.min(window.innerWidth*.6,resize.width+event.clientX-resize.x));}
</script>

<style scoped>
.marking-library{display:flex;flex-direction:column;gap:12px;min-width:0;min-height:0;height:100%;box-sizing:border-box;padding:16px;background:var(--panel);border-left:1px solid var(--border);overflow:hidden}.library-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:34px;padding-bottom:12px;border-bottom:1px solid var(--border)}.library-heading strong{color:var(--text);font-size:13px;font-weight:600;line-height:1.5}.library-heading button{flex:none;width:28px;min-height:28px;padding:0;color:var(--text-muted);font-size:19px;background:transparent}.marking-library>input{flex:none;margin:0;padding:8px 10px;font-size:12px}
.library-batch{display:flex;flex-wrap:wrap;gap:6px;margin:0}.library-batch button{min-height:29px;padding:5px 8px;font-size:11px}.library-batch button:last-child{color:var(--danger)}.library-zoom{display:flex;align-items:center;gap:10px;margin:0;color:var(--text-muted);font-size:11px;line-height:1.5;white-space:nowrap}.library-zoom input{flex:1;width:80px;min-width:48px;margin:0}.library-zoom span{flex:none;min-width:36px;color:var(--text-muted);font-variant-numeric:tabular-nums}.drag-help{margin:0;color:var(--text-muted);font-size:11px;line-height:1.65}
.library-content{display:grid;flex:1;min-width:0;min-height:0;overflow:hidden}.library-groups{min-width:0;min-height:0;overflow:auto;padding:0 2px 4px}.library-groups h3{margin:18px 0 10px;color:var(--text-muted);font-size:11px;font-weight:600;line-height:1.5}.library-groups>section:first-child h3{margin-top:4px}.library-groups p{margin:12px 0;color:var(--text-muted);font-size:11px;line-height:1.7}.region-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,var(--region-size)),1fr));gap:10px}.region-tile{position:relative;min-width:0}.region-card{display:flex;flex-direction:column;gap:8px;width:100%;height:100%;min-width:0;padding:7px;border:1px solid var(--border);border-radius:var(--radius-control);background:var(--panel);text-align:left;box-shadow:none}.region-card svg{display:block;width:100%;height:var(--preview-height,85px);border-radius:5px;background:var(--canvas)}.region-card small{display:block;margin:0 2px 2px;color:var(--text);font-size:11px;line-height:1.5;overflow-wrap:anywhere}.region-card.active{border-color:var(--accent);background:var(--selected);outline:1px solid var(--accent);outline-offset:-1px}.region-check{position:absolute;top:12px;left:12px;width:15px!important;height:15px;margin:0;accent-color:var(--accent);cursor:pointer}.region-delete{position:absolute;top:10px;right:10px;display:grid;place-items:center;width:24px;min-height:24px;padding:0;border:1px solid var(--border);border-radius:6px;background:var(--panel);color:var(--text-muted);font-size:17px;line-height:1}.region-delete:hover:not(:disabled){border-color:var(--danger);background:var(--danger-soft);color:var(--danger)}
.source-metadata{display:grid;gap:12px;min-width:0;margin:0;padding:0;border:0}.region-settings{display:block;min-width:0;min-height:0;overflow:auto;padding:12px 2px 0;border-top:1px solid var(--border)}.region-settings>*{margin-bottom:12px}.region-settings label{font-size:11px;line-height:1.6}.region-settings input:not([type=checkbox]),.region-settings select{padding:7px 8px}.region-settings input[type=color]{min-height:32px;padding:3px}.region-settings button{max-width:100%;min-height:32px;padding:7px 9px;font-size:11px;line-height:1.5;white-space:normal}.region-settings>.primary{width:100%}.open-marking-editor{display:flex;align-items:center;justify-content:center;gap:7px}.open-marking-editor .tool-icon{width:17px;height:17px}.region-settings details>*{margin-block:8px}.region-settings small{display:block;color:var(--text-muted);font-size:11px;line-height:1.65}.region-settings .two-col{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px}.region-settings .check-label{align-items:flex-start}.region-settings .check-label input{flex:none;margin-top:3px}.region-settings .attach-notice{padding:10px 12px;border:1px solid var(--border);border-radius:var(--radius-control);background:var(--panel-soft);color:var(--text);font-size:11px;line-height:1.65}
.delete-confirm{flex:none;padding:12px;border:1px solid var(--border);border-radius:var(--radius-control);background:var(--panel-soft);font-size:11px}.delete-confirm p{margin:0 0 10px;color:var(--text-muted);line-height:1.7}.delete-confirm button{max-width:100%;min-height:29px;margin:0 6px 6px 0;padding:5px 8px;font-size:11px;line-height:1.5;white-space:normal}.delete-confirm button:first-of-type{color:var(--danger)}
.detail-resizer{display:flex;align-items:center;justify-content:center;cursor:row-resize;touch-action:none;background:var(--panel)}.detail-resizer span{width:42px;height:3px;border-radius:2px;background:var(--border)}.detail-resizer:hover span,.detail-resizer:focus-visible span{background:var(--accent)}.drawer{position:relative;flex-shrink:0;border-left:0;border-right:1px solid var(--border)}.drawer.closed{gap:0;padding:8px}.drawer.closed .library-heading{justify-content:center;min-height:30px;padding:0;border-bottom:0}.drawer-resizer{position:absolute;right:0;top:0;bottom:0;width:5px;cursor:col-resize;touch-action:none}.drawer-resizer:hover{background:var(--accent-soft)}
@media(max-width:1100px){.marking-library{padding:12px;gap:10px}.library-batch{gap:4px}.library-batch button{padding-inline:6px;font-size:10px}.region-grid{gap:8px}}
</style>
